INSERT INTO `object_store_FAQ` VALUES
(12,'Do you offer returns?','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(21, 21, 21);\">Yes! If you&#039;re not 100% satisfied with your purchase, we offer a 30-day return policy on all products.</span></p>'),
(13,'What‚Äôs the quality of your products?','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(21, 21, 21);\">We prioritize quality in every item we sell. Our products are designed to be durable, functional, and stylish.</span></p>'),
(24,'Do you ship internationally?','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(21, 21, 21);\">Absolutely. We offer worldwide shipping, so you can enjoy our products no matter where you are.</span></p><p></p>'),
(25,'How long will my order take to arrive?','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(21, 21, 21);\">Shipping times vary by location, but we aim to deliver within 5-10 business days for most orders.</span></p><p></p>'),
(26,'Are your products environmentally friendly?','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(21, 21, 21);\">We are committed to sustainability and use eco-friendly materials whenever possible in the production and packaging of our products.</span></p><p></p>');
/*!40000 ALTER TABLE `object_store_FAQ` ENABLE KEYS */;
UNLOCK TABLES;

